"""The six reference pictures of post-processing are generated by one script and stay generated by it (#62).

A gallery that only exists as committed PNGs rots the first time a default changes. These tests run the script that
draws it: the six files have to come out of one call, be real images, and carry the captions the page uses. On a
machine without a GL context the rendering is skipped — the images in the repository are the record of a machine that
had one.
"""
from __future__ import annotations

import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))


def _gallery():
    pytest.importorskip("pyvista")
    import pyvista as pv

    pv.OFF_SCREEN = True
    try:                                                     # a headless machine without GL cannot render
        plotter = pv.Plotter(off_screen=True)
        plotter.add_mesh(pv.Sphere())
        plotter.close()
    except Exception as exc:                                 # noqa: BLE001 - any renderer failure means "cannot render"
        pytest.skip(f"pyvista cannot render here: {exc}")
    import gallery_postprocessing as gallery

    return gallery


def test_the_script_writes_the_six_pictures(tmp_path):
    gallery = _gallery()
    written = gallery.build(tmp_path, (400, 300))
    assert len(written) == 6
    names = [path.name for path in written]
    assert names == [f"{key}.png" for key in gallery.CAPTIONS]
    for path in written:
        assert path.exists() and path.stat().st_size > 2_000, f"{path} is empty"


def test_every_picture_has_a_caption_for_the_page():
    gallery = _gallery()
    assert len(gallery.CAPTIONS) == 6
    assert all(len(caption) > 20 for caption in gallery.CAPTIONS.values())


def test_the_committed_gallery_matches_the_script():
    """The page embeds these files by name: a renamed picture is a broken page."""
    gallery = _gallery()
    folder = ROOT / "docs" / "assets" / "postprocessing"
    committed = sorted(p.name for p in folder.glob("*.png"))
    assert committed == sorted(f"{key}.png" for key in gallery.CAPTIONS)


def test_the_field_is_the_same_every_run():
    gallery = _gallery()
    first, second = gallery.field(16), gallery.field(16)
    assert (first["speed"] == second["speed"]).all()
    assert 0.0 <= float(first["speed"].min()) and float(first["speed"].max()) < 5.0
